{
  "name": "CCD探测器",
  "name_en": "CCD Detector",
  "manufacturer": "HORIBA",
  "description": "用于光谱测量的电荷耦合器件探测器，可将入射光转换为数字信号并输出光谱或图像数据。常见于光谱仪、单色仪或拉曼系统中，支持曝光、增益、读出速度、感兴趣区域、触发和波长相关设置；部分型号可提供EM增益。",
  "description_en": "A charge-coupled device detector used for optical measurements, converting incident light into digital spectral or imaging data. It is commonly integrated with spectrometers, monochromators, or Raman systems, and supports configuration of exposure, gain, readout speed, region of interest, triggering, and wavelength-related settings; some models provide EM gain.",
  "tag_hints": [
    "CCD detector",
    "EMCCD",
    "optical spectroscopy",
    "Raman spectroscopy",
    "monochromator coupling",
    "ROI acquisition",
    "triggered acquisition"
  ],
  "actions": [
    {
      "action_name": "auto-open",
      "description": "打开与CCD探测器的连接",
      "description_en": "Open the connection to the CCD detector"
    },
    {
      "action_name": "auto-close",
      "description": "关闭与CCD探测器的连接",
      "description_en": "Close the connection to the CCD detector"
    },
    {
      "action_name": "auto-is_open",
      "description": "检查与CCD探测器的连接是否已打开",
      "description_en": "Check whether the connection to the CCD detector is open"
    },
    {
      "action_name": "auto-restart",
      "description": "重启CCD探测器",
      "description_en": "Restart the CCD detector"
    },
    {
      "action_name": "auto-set_gain",
      "description": "设置探测器增益",
      "description_en": "Set the detector gain"
    },
    {
      "action_name": "auto-set_speed",
      "description": "设置读出速度",
      "description_en": "Set the readout speed"
    },
    {
      "action_name": "auto-set_parallel_speed",
      "description": "设置并行读出速度",
      "description_en": "Set the parallel readout speed"
    },
    {
      "action_name": "auto-set_fit_parameters",
      "description": "设置拟合参数",
      "description_en": "Set the fit parameters"
    },
    {
      "action_name": "auto-set_timer_resolution",
      "description": "设置定时分辨率",
      "description_en": "Set the timer resolution"
    },
    {
      "action_name": "auto-set_acquisition_format",
      "description": "设置采集格式和ROI数量",
      "description_en": "Set the acquisition format and number of ROIs"
    },
    {
      "action_name": "auto-set_region_of_interest",
      "description": "设置感兴趣区域（ROI）",
      "description_en": "Set the region of interest (ROI)"
    },
    {
      "action_name": "auto-set_x_axis_conversion_type",
      "description": "设置X轴像素转换类型",
      "description_en": "Set the X-axis pixel conversion type"
    },
    {
      "action_name": "auto-set_acquisition_count",
      "description": "设置顺序采集次数",
      "description_en": "Set the number of sequential acquisitions"
    },
    {
      "action_name": "auto-set_clean_count",
      "description": "设置测量前清洗次数及模式",
      "description_en": "Set the pre-measurement clean count and mode"
    },
    {
      "action_name": "auto-set_exposure_time",
      "description": "设置曝光时间",
      "description_en": "Set the exposure time"
    },
    {
      "action_name": "auto-set_trigger_input",
      "description": "设置输入触发参数",
      "description_en": "Set the input trigger parameters"
    },
    {
      "action_name": "auto-set_signal_output",
      "description": "设置信号输出参数",
      "description_en": "Set the signal output parameters"
    },
    {
      "action_name": "auto-acquisition_start",
      "description": "开始采集",
      "description_en": "Start acquisition"
    },
    {
      "action_name": "auto-acquisition_abort",
      "description": "中止采集",
      "description_en": "Abort acquisition"
    },
    {
      "action_name": "auto-set_center_wavelength",
      "description": "设置中心波长",
      "description_en": "Set the center wavelength"
    },
    {
      "action_name": "auto-range_mode_center_wavelengths",
      "description": "根据波长范围和像素重叠计算中心波长序列",
      "description_en": "Calculate a sequence of center wavelengths from a wavelength range and pixel overlap"
    },
    {
      "action_name": "auto-set_em_gain",
      "description": "设置EM增益",
      "description_en": "Set the EM gain"
    }
  ]
}

